import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"收藏夹","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/favorites.md","filePath":"zh-CN/user-guide/settings/favorites.md","lastUpdated":1785993908000}'),s={name:"zh-CN/user-guide/settings/favorites.md"};function n(i,t,l,d,h,g){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="收藏夹" tabindex="-1">收藏夹 <a class="header-anchor" href="#收藏夹" aria-label="Permalink to &quot;收藏夹&quot;">​</a></h1><p>把常用的文件夹、文件或网址固定下来，一个按键就能到达。</p><h2 id="添加收藏" tabindex="-1">添加收藏 <a class="header-anchor" href="#添加收藏" aria-label="Permalink to &quot;添加收藏&quot;">​</a></h2><ul><li><strong>显示名称</strong> —— 可选;如果留空且目标是本地路径，会自动用路径的文件名填充。</li><li><strong>目标路径</strong> —— 本地路径，或者 <code>http://</code>/<code>https://</code> 网址。</li><li><strong>浏览文件夹</strong> / <strong>浏览文件</strong> 按钮 —— 打开原生选择器，不用手动输路径。</li><li><strong>添加</strong> 按钮 —— 输入路径后才可用。</li></ul><h2 id="管理列表" tabindex="-1">管理列表 <a class="header-anchor" href="#管理列表" aria-label="Permalink to &quot;管理列表&quot;">​</a></h2><p>列表里每一条收藏都显示名称和目标路径，每行带独立操作:</p><ul><li><strong>向上移动</strong> / <strong>向下移动</strong> —— 调整顺序，同时也会影响该收藏项在搜索结果里相对其他结果的排名。每一行也可以直接拖动左边的六点手柄来调整顺序——设置里所有可排序列表(结果类型优先级、快速导航顺序、侧边栏筛选顺序、结果表格列顺序)用的都是同一个拖拽手柄。</li><li><strong>编辑此项</strong> —— 把该项加载回上方输入框以便修改。</li><li><strong>删除此项</strong> —— 移除。</li></ul><h2 id="收藏项如何出现在搜索里" tabindex="-1">收藏项如何出现在搜索里 <a class="header-anchor" href="#收藏项如何出现在搜索里" aria-label="Permalink to &quot;收藏项如何出现在搜索里&quot;">​</a></h2><p>命中的收藏项会在结果里带一个 <strong>★</strong> 标记，紧跟在文件夹/路径标签旁边，并且可以用它的显示名称搜索到——如果名称里含中文，同样支持拼音，和其他任何结果一样。这是 Lertaro 里最接近&quot;自定义搜索别名&quot;的功能，参见<a href="./../search-syntax.html#收藏夹-而非自定义别名">搜索语法</a>。</p>',9)])])}const _=a(s,[["render",n]]);export{u as __pageData,_ as default};
